import * as THREE from 'three';
import {sceneRendering} from '../scene-rendering.js';
import {makeSceneComponent} from '../scene-components.js';
import {create2DAsset} from '../two-d-assets.js';

export async function runTwoDLightingCase({renderer,scene,camera,groups,group,layers,pixel,expect}){
  let checks=0;const evidence=[],frames=[],check=(test,label)=>{checks++;if(!test)window.__hbLight2DFailure={label,evidence,image:renderer.domElement.toDataURL()};expect(test,label);};
  const image=(color)=>{const c=document.createElement('canvas');c.width=c.height=16;const x=c.getContext('2d');x.fillStyle=color;x.fillRect(0,0,16,16);return c.toDataURL();},sources={'white.png':image('white'),'tilt.png':image('rgb(255,128,128)')};
  const assets={},visuals=sceneRendering({read:async p=>assets[p],fileUrl:p=>sources[p],loadModel:async()=>{throw Error('unexpected model');},current:id=>groups.find(g=>g.userData.objectId===id),all:()=>groups,error:e=>{throw Error(e);}});
  const actor={id:'light2d-sprite',kind:'sprite',components:[makeSceneComponent('SpriteRenderer',{texture:'white.png',shading:'lit2d',width:2,height:2})]},sprite=group(actor.id);
  const lamp=group('light2d-lamp'),light={id:'light2d-lamp',kind:'empty',components:[makeSceneComponent('Light2D',{lightType:'global'})]};
  const p=()=>lamp.userData.light2d,black=v=>v.slice(0,3).every(n=>n<5),white=v=>v.slice(0,3).every(n=>n>245),red=v=>v[0]>245&&v[1]<5&&v[2]<5;
  const render=()=>{const state=visuals.prepare2D(renderer,scene,camera,layers);renderer.render(scene,camera);return {state,pixel:pixel()};},shot=label=>{const canvas=document.createElement('canvas');canvas.width=canvas.height=64;canvas.getContext('2d').drawImage(renderer.domElement,0,0);frames.push({label,canvas});};
  try{
    await visuals.build(actor,sprite);check(black(render().pixel),'unlit by absent dedicated 2D lights');
    await visuals.build(light,lamp);check(white(render().pixel),'global Light2D lights sprite without 3D lights');shot('2D Global');
    const version=visuals.prepare2D(renderer,scene,camera,layers).lightUploads;check(render().state.lightUploads===version,'unchanged lighting does not upload texture again');
    lamp.rotation.x=Math.PI/2;check(white(render().pixel),'global light ignores pose including edge-on rotation');lamp.rotation.x=0;
    p().color=[1,0,0,1];check(red(render().pixel),'2D light color reaches GPU');
    const unrelated=new THREE.PointLight(0x00ff00,100,10);unrelated.position.set(0,0,2);scene.add(unrelated);check(red(render().pixel),'dedicated lighting ignores 3D lights');unrelated.removeFromParent();
    p().targetSortingLayers=['front'];check(black(render().pixel),'target layer exclusion');actor.components[0].properties.sortingLayer='front';await visuals.spriteFrame(actor,'');check(red(render().pixel),'target layer inclusion');
    const many=Array.from({length:64},(_,i)=>({id:i?'layer'+i:'default',name:'Layer '+i}));sprite.userData.spriteMesh.userData.draw2d.sortingLayer='layer63';p().targetSortingLayers=['layer63'];visuals.prepare2D(renderer,scene,camera,many);renderer.render(scene,camera);check(red(pixel()),'layer63 mask remains exact above32');
    actor.components[0].properties.sortingLayer='default';sprite.userData.spriteMesh.userData.draw2d.sortingLayer='default';Object.assign(p(),{lightType:'point',color:[1,1,1,1],targetSortingLayers:['default'],innerRadius:1,outerRadius:2,normalMode:'disabled'});lamp.position.set(0,0,-70);check(white(render().pixel),'point Light2D ignores negative light Z');lamp.position.z=70;check(white(render().pixel),'point Light2D ignores positive light Z');sprite.position.z=-30;check(white(render().pixel),'point Light2D ignores sprite Z');sprite.position.z=0;
    lamp.position.set(5,0,0);check(black(render().pixel),'point outer radius clips illumination');lamp.position.set(1.5,0,0);const soft=render().pixel;p().falloff=4;const hard=render().pixel;check(soft[0]>hard[0]+40,'falloff changes radial edge');
    Object.assign(p(),{lightType:'spot',innerRadius:0,outerRadius:5,innerAngle:40,outerAngle:80,falloff:1});lamp.position.set(0,-1,0);check(render().pixel[0]>200,'spot points along local positive Y');lamp.rotation.z=Math.PI;check(black(render().pixel),'spot rotation turns cone away');lamp.rotation.z=0;render();shot('2D Spot');
    Object.assign(p(),{lightType:'point',innerRadius:2,normalMode:'accurate',normalDistance:1});lamp.position.set(0,0,50);const accurate=render();const accurateEdge=pixel(44,32);p().normalMode='fast';render();const fastEdge=pixel(44,32);check(fastEdge[0]>accurateEdge[0]+12,'Fast uses center direction while Accurate uses each fragment');p().normalMode='accurate';p().normalDistance=.1;render();check(pixel(44,32)[0]<accurateEdge[0]-30,'simulated normal distance changes direction without changing range');
    actor.components[0].properties.normalTexture='tilt.png';await visuals.spriteFrame(actor,'');p().normalDistance=1;check(render().pixel[0]<20,'linear normal map changes dedicated 2D light');p().normalMode='disabled';check(white(render().pixel),'disabled normal calculation bypasses map response');shot('Normal disabled');
    const parent=new THREE.Group();scene.add(parent);parent.add(lamp);parent.position.set(10,0,7);lamp.position.set(-10,0,-90);check(white(render().pixel),'parented world XY transforms drive 2D light');parent.scale.set(2,1,1);lamp.position.x=-5;check(white(render().pixel),'nonuniform XY scale supports light center');parent.remove(lamp);scene.add(lamp);parent.removeFromParent();lamp.position.set(0,0,0);
    p().enabled=false;check(black(render().pixel)&&render().state.lightBytes===0,'disabled last light releases data texture');p().enabled=true;lamp.visible=false;check(black(render().pixel),'hidden light does not illuminate');lamp.visible=true;
    const mask=group('light2d-mask');await visuals.build({id:'light2d-mask',kind:'empty',components:[makeSceneComponent('SpriteMask',{width:.5,height:2})]},mask);actor.components[0].properties.maskInteraction='inside';await visuals.spriteFrame(actor,'');render();check(white(pixel())&&black(pixel(44,32)),'dedicated lighting composes with SpriteMask');visuals.dispose(mask);mask.removeFromParent();groups.splice(groups.indexOf(mask),1);
    visuals.dispose(sprite);sprite.removeFromParent();groups.splice(groups.indexOf(sprite),1);
    const map={...create2DAsset('tilemap','2DLights'),tileset:'white.png',tileSize:[16,16],cellSize:[2,2]};map.layers[0].tiles=[{x:0,y:0,index:0}];assets['tiles.json']=map;const tile=group('light2d-tile');tile.position.set(-1,1,0);await visuals.build({id:'light2d-tile',kind:'tilemap',components:[makeSceneComponent('TilemapRenderer',{tilemap:'tiles.json',shading:'lit2d'})]},tile);check(white(render().pixel),'tile layer receives same dedicated 2D light');shot('2D Tile');
    const overflow=[];for(let i=0;i<64;i++){const g=group('extra-light-'+i);g.userData.light2d={...p()};overflow.push(g);}let limited=false;try{render();}catch(e){limited=e.message.includes('64');}check(limited,'light limit rejects instead of silently dropping lamps');for(const g of overflow){g.removeFromParent();groups.splice(groups.indexOf(g),1);}
    check(renderer.info.programs.every(p=>p.diagnostics?.runnable!==false),'dedicated lighting GPU shaders compile');evidence.push({kind:'normal-modes',accurate:accurateEdge,fast:fastEdge,radialSoft:soft,radialHard:hard});
    const proof=document.createElement('canvas');proof.width=256;proof.height=frames.length*86;const c=proof.getContext('2d');c.fillStyle='#202226';c.fillRect(0,0,proof.width,proof.height);frames.forEach((f,i)=>{c.drawImage(f.canvas,0,i*86,64,64);c.fillStyle='white';c.font='13px sans-serif';c.fillText(f.label,72,i*86+34);});return {checks,evidence,image:proof.toDataURL()};
  }finally{for(const g of groups.splice(0)){visuals.dispose(g);g.removeFromParent();}visuals.dispose2D();}
}
